/* SPDX-License-Identifier: GPL-2.0-or-later
 * Dump the tables the WheelBox firmware needs from the unmodified setBfree
 * tone generator: wheel frequencies/attenuations, the key-contact matrix,
 * the key-compression curve and the click envelopes.
 *
 * Build: make -C tools/setbfree-host
 * Run:   tools/setbfree-host/dump_tables --summary
 *        tools/setbfree-host/dump_tables --header app/dsp/organ_tables.h
 *
 * The generated header is GPL-2.0-or-later (it is derived from setBfree's
 * configuration model). It is regenerated by the build, not edited by hand.
 */
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "host.h"
#include "tonegen.h"

static int16_t q15(double x)
{
    double v = rint(x * 32768.0);
    if (v > 32767.0)
        v = 32767.0;
    if (v < -32768.0)
        v = -32768.0;
    return (int16_t)v;
}

static uint32_t q32inc(double hz, double sr)
{
    return (uint32_t)llrint(hz / sr * 4294967296.0);
}

/* Q24: levels run from ~4e-5 (crosstalk) to ~2.2 (a taper sum). */
static int32_t q24(double x)
{
    double v = rint(x * 16777216.0);
    if (v > 2147483647.0)
        v = 2147483647.0;
    if (v < -2147483648.0)
        v = -2147483648.0;
    return (int32_t)v;
}

static const char *arg_value(int argc, char **argv, const char *name)
{
    int i;
    for (i = 1; i + 1 < argc; i++)
        if (!strcmp(argv[i], name))
            return argv[i + 1];
    return NULL;
}

int main(int argc, char **argv)
{
    const char *header = arg_value(argc, argv, "--header");
    const char *sr_s = arg_value(argc, argv, "--fs");
    double sr = sr_s ? atof(sr_s) : 44100.0;
    struct b_tonegen *t;
    int k, i, b;
    int total = 0, max_per_key = 0, max_key = 0;
    double max_level = 0.0;
    FILE *f = NULL;

    SampleRateD = sr;
    SampleRateI = (int)(sr + 0.5);
    t = allocTonegen();
    if (!t) {
        fprintf(stderr, "dump_tables: out of memory\n");
        return 1;
    }
    initToneGenerator(t, NULL);

    for (k = 0; k < MAX_KEYS; k++) {
        int n = 0;
        double mx = 0.0;
        ListElement *e;
        for (e = t->keyContrib[k]; e; e = e->next) {
            double lv = e->u.ssf.fc;
            n++;
            if (lv > mx)
                mx = lv;
        }
        total += n;
        if (n > max_per_key)
            max_per_key = n;
        if (mx > max_level)
            max_level = mx;
        if (k < 64 && mx > 0.0 && max_key == 0)
            max_key = k;
    }

    printf("setBfree tables @ %.1f Hz\n", sr);
    printf("  wheels: %d\n", NOF_WHEELS);
    printf("  key contributions: %d total, %d max/key, max level %.4f\n", total, max_per_key, max_level);
    printf("  frequency range: %.2f .. %.2f Hz\n", t->oscillators[1].frequency, t->oscillators[NOF_WHEELS].frequency);
    printf("  attenuation range: %.4f .. %.4f\n", t->oscillators[1].attenuation, t->oscillators[NOF_WHEELS].attenuation);
    printf("  keyComp: %.3f .. %.3f (128 keys)\n", t->keyCompTable[0], t->keyCompTable[127]);

    {
        double bytes = 0.0;
        for (i = 1; i <= NOF_WHEELS; i++)
            bytes += (double)t->oscillators[i].lengthSamples * 4.0;
        printf("  wave tables: %.1f KB (float), %.1f KB (int16)\n", bytes / 1024.0, bytes / 2048.0);
    }

    if (!header)
        return 0;

    f = fopen(header, "w");
    if (!f) {
        perror(header);
        return 1;
    }
    fprintf(f, "/* Generated by tools/setbfree-host/dump_tables from setBfree\n"
               " * (GPL-2.0-or-later). Do not edit. */\n"
               "#ifndef WB_ORGAN_TABLES_H\n#define WB_ORGAN_TABLES_H\n\n"
               "#include <stdint.h>\n\n"
               "#define WB_FS %d\n#define WB_WHEELS %d\n#define WB_KEYS %d\n"
               "#define WB_CONTRIBS %d\n\n"
               "/* level is Q24 (divide by 16777216.0f) */\n"
               "typedef struct { uint8_t wheel, bus; int32_t level; } wb_contrib_t;\n\n",
            (int)(sr + 0.5), NOF_WHEELS, MAX_KEYS, total);
    fprintf(f, "static const uint32_t wb_wheel_inc[WB_WHEELS + 1] = {\n");
    for (i = 0; i <= NOF_WHEELS; i++)
        fprintf(f, "    %uu,%s", q32inc(i ? t->oscillators[i].frequency : 0.0, sr), (i % 8 == 7) ? "\n" : " ");
    fprintf(f, "\n};\n\nstatic const int16_t wb_wheel_att[WB_WHEELS + 1] = {\n");
    for (i = 0; i <= NOF_WHEELS; i++)
        fprintf(f, "    %d,%s", q15(i ? t->oscillators[i].attenuation : 0.0), (i % 12 == 11) ? "\n" : " ");
    fprintf(f, "\n};\n\nstatic const int16_t wb_key_comp[128] = {\n");
    for (i = 0; i < 128; i++)
        fprintf(f, "    %d,%s", q15(t->keyCompTable[i]), (i % 12 == 11) ? "\n" : " ");
    fprintf(f, "\n};\n\nstatic const int16_t wb_attack_env[9][128] = {\n");
    for (b = 0; b < 9; b++) {
        fprintf(f, "    {");
        for (i = 0; i < 128; i++)
            fprintf(f, "%d%s", q15(t->attackEnv[b][i]), i == 127 ? "" : ",");
        fprintf(f, "},\n");
    }
    fprintf(f, "};\n\nstatic const int16_t wb_release_env[9][128] = {\n");
    for (b = 0; b < 9; b++) {
        fprintf(f, "    {");
        for (i = 0; i < 128; i++)
            fprintf(f, "%d%s", q15(t->releaseEnv[b][i]), i == 127 ? "" : ",");
        fprintf(f, "},\n");
    }
    fprintf(f, "};\n\nstatic const uint32_t wb_contrib_index[WB_KEYS + 1] = {\n");
    {
        int at = 0;
        for (k = 0; k <= MAX_KEYS; k++) {
            fprintf(f, "    %d,%s", at, (k % 12 == 11) ? "\n" : " ");
            if (k == MAX_KEYS)
                break;
            for (ListElement *e = t->keyContrib[k]; e; e = e->next)
                at++;
        }
        fprintf(f, "\n};\n\nstatic const wb_contrib_t wb_contrib[WB_CONTRIBS] = {\n");
        for (k = 0; k < MAX_KEYS; k++) {
            for (ListElement *e = t->keyContrib[k]; e; e = e->next)
                fprintf(f, "    {%d,%d,%d},\n", e->u.ssf.sa, e->u.ssf.sb, q24(e->u.ssf.fc));
        }
        fprintf(f, "};\n\n#endif /* WB_ORGAN_TABLES_H */\n");
    }
    fclose(f);
    printf("wrote %s\n", header);
    return 0;
}
